      timestamp: new Date().toISOString() 
    });
  }
});

app.get('/users', validateQuery(['limit', 'offset']), (req, res, next) => {
  try {
    const { limit, offset } = req.query;

    // Validate numeric parameters
    const limitNum = limit ? parseInt(limit, 10) : undefined;
    const offsetNum = offset ? parseInt(offset, 10) : undefined;

    if (limit && (isNaN(limitNum) || limitNum < 1 || limitNum > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter: must be between 1 and 100'
      });
    }

    if (offset && (isNaN(offsetNum) || offsetNum < 0)) {
      return res.status(400).json({
        error: 'Invalid offset parameter: must be non-negative'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if valid
    const paginatedUsers = users.slice(offsetNum || 0, limitNum ? (limitNum + (offsetNum || 0)) : undefined);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit: limitNum || users.length,
        offset: offsetNum || 0
      }
    });
  } catch (error) {
    next(error);
  }
});
```

### 6. **404 Handler**
Add proper handling for undefined routes:

```javascript
// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
    timestamp: new Date().toISOString()
  });
});
```

### 7. **Safe Expression Handling**
Avoid `res.send()` with untrusted user input to prevent XSS:

```javascript
// Always use res.json() for structured data
// Or escape HTML if using res.send() for text
const escapeHtml = (text) => {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};
```

### 8. **Environment-Specific Error Handling**
Add environmental awareness for error responses:

```javascript
// Add this before error handling middleware
const isDevelopment = process.env.NODE_ENV !== 'production';

// Enhanced error handling middleware
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;

  const errorResponse = {
    error: process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message,
    timestamp: new Date().toISOString(),
    ...(isDevelopment && { stack: err.stack })
  };

  res.status(statusCode).json(errorResponse);
});
```

### 9. **Consider Adding These Packages**
For a production application, also consider adding:
- `express-validator` or `joi` for schema validation
- `helmet` for security headers
- `rate-limiter-flexible` for robust rate limiting
- `cors` for proper CORS configuration

### 10. **Configuration Security**
Incorporate the `.env` file pattern for configuration:

```javascript
// Add at the top of your app
require('dotenv').config();

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});
```

