const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResults } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Parse JSON bodies with size limit
app.use(express.json({ limit: '100kb' }));
app.use(express.urlencoded({ extended: true, limit: '100kb' }));

// Error handling middleware for validation
const handleValidationErrors = (req, res, next) => {
  const errors = validationResults(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with example input validation
app.get('/users', handleValidationErrors, (req, res) => {
  // Example: adding validation for optional query parameters
  const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;

  // Validate limit is a number and within reasonable range
  if (req.query.limit && (isNaN(limit) || limit < 1 || limit > 100)) {
    return res.status(400).json({ 
      error: 'Invalid limit parameter', 
      message: 'Limit must be a number between 1 and 100' 
    });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example parameterized endpoint with validation
app.get('/users/:id', handleValidationErrors, (req, res) => {
  const userId = parseInt(req.params.id, 10);

  // Validate ID is a positive integer
  if (isNaN(userId) || userId < 1) {
    return res.status(400).json({ 
      error: 'Invalid user ID', 
      message: 'User ID must be a positive integer' 
    });
  }

  // In a real app, you would query the database here
  if (userId > 2) {
    return res.status(404).json({ error: 'User not found' });
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users.find(u => u.id === userId));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error details (in production, use a proper logging service)
  console.error('Error:', err.message, err.stack);

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.statusCode || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

