// Secure Express application with proper error handling and input validation
// Security improvements implemented per OWASP best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const Joi = require('joi'); // Input validation library

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Add security headers using helmet
app.use(helmet());

// 2. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. Body parsing with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// INPUT VALIDATION SCHEMAS
// ============================================

// Validation schema for users endpoint query parameters
const usersQuerySchema = Joi.object({
  limit: Joi.number()
    .integer()
    .min(1)
    .max(100)
    .default(10),
  offset: Joi.number()
    .integer()
    .min(0)
    .default(0),
  sort: Joi.string()
    .valid('id', 'name', 'email')
    .default('id'),
  order: Joi.string()
    .valid('asc', 'desc')
    .default('asc')
});

// ============================================
// REQUEST VALIDATION MIDDLEWARE
// ============================================

// Generic validation middleware
const validate = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query || req.body || req.params);

    if (error) {
      return res.status(400).json({
        error: 'Validation Error',
        details: error.message,
        timestamp: new Date().toISOString()
      });
    }

    // Replace req.query/req.body with validated value
    if (req.query) req.query = value;
    if (req.body) req.body = value;
    if (req.params) req.params = value;

    next();
  };
};

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// Global error handler
const errorHandler = (err, req, res, next) => {
  // Log error details securely (without exposing sensitive system info)
  console.error('[ERROR]', {
    message: err.message,
    name: err.name,
    timestamp: new Date().toISOString(),
    // Don't log full stack trace in production
    // stack: err.stack // Commented for security in production
  });

  // Default error response
  const statusCode = err.statusCode || err.status || 500;

  // Prevent information leakage
  const isProduction = process.env.NODE_ENV === 'production';

  const errorResponse = {
    error: err.name || 'Internal Server Error',
    message: isProduction 
      ? 'An error occurred processing your request' 
      : err.message,
    timestamp: new Date().toISOString()
  };

  // Only include stack trace in development
  if (!isProduction && err.stack) {
    errorResponse.stack = err.stack;
  }

  // Send standardized error response
  res.status(statusCode).json(errorResponse);
};

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    timestamp: new Date().toISOString()
  });
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint (no validation needed)
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    errorHandler(error, req, res, () => {});
  }
});

// Users endpoint with validation
app.get('/users', validate(usersQuerySchema), (req, res) => {
  try {
    // Simulated database query with input validation
    const { limit, offset, sort, order } = req.query;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sort and paginate results (input is already validated)
    const sortedUsers = users.sort((a, b) => {
      const aValue = a[sort];
      const bValue = b[sort];
      return order === 'asc' 
        ? aValue > bValue ? 1 : -1 
        : aValue < bValue ? 1 : -1;
    });

    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.status(200).json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: sortedUsers.length
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    errorHandler(error, req, res, () => {});
  }
});

// ============================================
// START SERVER
// ============================================

// Use PORT from environment or default to 3000
const PORT = process.env.PORT || 3000;

// Start server with proper error handling
try {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Handle server errors
  server.on('error', (err) => {
    console.error('[SERVER ERROR]', {
      message: err.message,
      code: err.code,
      timestamp: new Date().toISOString()
    });

    // Graceful shutdown on port binding errors
    if (err.code === 'EADDRINUSE') {
      console.error(`Port ${PORT} is already in use`);
      process.exit(1);
    }
  });

  // Handle uncaught exceptions (with timeout to allow error response)
  process.on('uncaughtException', (err) => {
    console.error('[UNCAUGHT EXCEPTION]', {
      message: err.message,
      timestamp: new Date().toISOString()
    });

    // Allow some time for error logging/sentry before exiting
    setTimeout(() => process.exit(1), 1000);
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('[UNHANDLED REJECTION]', {
      reason: reason instanceof Error ? reason.message : String(reason),
      timestamp: new Date().toISOString()
    });
  });

} catch (error) {
  console.error('[STARTUP ERROR]', {
    message: error.message,
    timestamp: new Date().toISOString()
  });
  process.exit(1);
}

module.exports = app;

